def seed_billing_periods_and_settings(apps, schema_editor):
    BillingPeriod = apps.get_model('core', 'BillingPeriod')
    PlatformBillingSettings = apps.get_model('core', 'PlatformBillingSettings')
    SchoolSubscription = apps.get_model('core', 'SchoolSubscription')
    Plan = apps.get_model('core', 'Plan')
    School = apps.get_model('core', 'School')

    # Seed billing periods (1, 4, 8, 12 months)
    defaults = [
        (1, Decimal('0.00'), 1),
        (4, Decimal('5.00'), 2),
        (8, Decimal('10.00'), 3),
        (12, Decimal('15.00'), 4),
    ]
    for m, disc, order in defaults:
        BillingPeriod.objects.get_or_create(
            months=m,
            defaults={'discount_percentage': disc, 'is_active': True, 'display_order': order}
        )

    # Seed default basic access features
    basic_features = [
        'school_setup',
        'people_accounts',
        'authentication',
        'password_change',
        'profile_view',
        'subscription_management',
        'order_submission',
        'support_contact',
        'compliance_export',
        'basic_reports_csv',
        'english_urdu',
    ]
    settings_obj = PlatformBillingSettings.objects.filter(id=1).first()
    if settings_obj:
        if not settings_obj.basic_access_features:
            settings_obj.basic_access_features = basic_features
            settings_obj.save(update_fields=['basic_access_features'])
    else:
        PlatformBillingSettings.objects.create(
            id=1,
            basic_access_features=basic_features
        )

    # Ensure existing demo schools keep active Premium
    premium_plan = Plan.objects.filter(code='premium').first()
    for school in School.objects.all():
        is_demo = ('demo' in (school.name or '').lower()) or ('northstar' in (school.name or '').lower()) or ('optimus' in (school.name or '').lower())
        sub = SchoolSubscription.objects.filter(school=school).first()
        if sub:
            if is_demo and premium_plan:
                sub.status = 'active'
                sub.plan = premium_plan
                sub.save(update_fields=['status', 'plan'])
            elif sub.status in ('trial', 'limited', 'pending_approval'):
                sub.status = 'no_plan'
                sub.save(update_fields=['status'])

    # Postgres grant
    if schema_editor.connection.vendor == 'postgresql':
        with schema_editor.connection.cursor() as cursor:
            cursor.execute("GRANT SELECT, INSERT, UPDATE, DELETE ON core_billingperiod TO PUBLIC;")


def reverse_seed(apps, schema_editor):
    pass


